namespace FastOrangeCombined {
    public class RawProxyValue {
        public string Path;
        public string Name;
        public bool Exists;
        public string Kind;
        public string Data;
    }
    public class ProxyProfile {
        public uint Flags;
        public string Server;
        public string Bypass;
        public string AutoUrl;
        public RawProxyValue[] Raw;
