                    finally {if(resource!=null)resource.Dispose();}
                    return;
                }
                Thread.Sleep(200);
            }
        }
        public void Dispose() {
            stopping=true;
            if(watcher!=null && watcher!=Thread.CurrentThread)watcher.Join(1500);
            try {Restore();}finally{if(resource!=null)resource.Dispose();}
        }
    }
}

